    static String t(Context context,String source){
        if(!"hinglish".equals(MitrioPreferences.get(context).getString("ui_language","english")))return source;
        String exact=HINGLISH.get(source);if(exact!=null)return exact;
        if(source.startsWith("Talk to "))return "Baat karein: "+source.substring("Talk to ".length());
        if(source.startsWith("Teach "))return "Sikhayein: "+source.substring("Teach ".length());
        if(source.startsWith("Assistant  ·  "))return "Assistant  ·  "+source.substring("Assistant  ·  ".length());
        if(source.startsWith("Choose check-in time · "))return "Check-in ka time · "+source.substring("Choose check-in time · ".length());
        if(source.startsWith("Good morning, "))return "Suprabhat, "+source.substring("Good morning, ".length());
        if(source.startsWith("Good afternoon, "))return "Namaste, "+source.substring("Good afternoon, ".length());
        if(source.startsWith("Good evening, "))return "Shubh sandhya, "+source.substring("Good evening, ".length());
        return source;
    }
    private UiStrings(){}
